toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 regardless of lines and subtotal", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 2)], 5000)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("throws for negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("throws for non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
  });

  it("throws for negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("throws for non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(500);
    expect(calc.computeShippingCents([], 1000)).toBe(0);
  });

  it("returns flat fee for non-empty cart", () => {
    const calc = new FlatShippingCalculator(799);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 2000)).toBe(799);
  });

  it("returns 0 when subtotal >= freeOverCents threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 6000)).toBe(0);
  });

  it("charges flat fee when subtotal < freeOverCents threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(500);
  });

  it("zero flatCents is valid and returns 0 shipping", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 1000)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("throws for empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("throws for bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("throws for bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("throws for negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 500, costCents: 100 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
    ]);
    expect(calc.computeShippingCents([], 1000)).toBe(0);
  });

  it("returns 0 when total weight is 0 (no weightGrams)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", undefined, 2)], 1000)).toBe(0);
  });

  it("selects correct bracket by weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 2000, costCents: 900 },
    ]);
    // 200g → first bracket
    expect(calc.computeShippingCents([makeLine("a", 200, 1)], 1000)).toBe(300);
    // 500g → exactly first bracket boundary
    expect(calc.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(300);
    // 501g → second bracket
    expect(calc.computeShippingCents([makeLine("a", 501, 1)], 1000)).toBe(600);
    // 1000g → exactly second bracket boundary
    expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 1000)).toBe(600);
    // 1500g → third bracket
    expect(calc.computeShippingCents([makeLine("a", 1500, 1)], 1000)).toBe(900);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      1200,
    );
    expect(calc.computeShippingCents([makeLine("a", 1500, 1)], 1000)).toBe(1200);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 1000)).toBe(600);
  });

  it("sorts brackets internally regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 2000, costCents: 900 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([makeLine("a", 400, 1)], 1000)).toBe(300);
    expect(calc.computeShippingCents([makeLine("a", 700, 1)], 1000)).toBe(600);
  });

  it("sums weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 200*2 + 300*1 = 700 → second bracket
    const lines = [makeLine("a", 200, 2), makeLine("b", 300, 1)];
    expect(calc.computeShippingCents(lines, 1000)).toBe(600);
  });
});

