+import { describe, it, expect, vi } from "vitest";
+import { Cart } from "../src/cart.ts";
+import { InventoryError } from "../src/inventory.ts";
+import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
+import type { AsyncTaxRateProvider } from "../src/tax.ts";
+import type { Product } from "../src/product.ts";
+import { PercentageDiscountPolicy } from "../src/pricing.ts";
+import { FlatShippingCalculator } from "../src/shipping.ts";
+
+const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
+const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };
+
+describe("Cart.checkout()", () => {
+  describe("price refresh", () => {
+    it("updates prices from priceFetcher before computing totals", async () => {
+      const cart = new Cart();
+      cart.add(productA, 2);
+      const priceFetcher: PriceFetcher = {
+        fetchPriceCents: vi.fn().mockResolvedValue(1500),
+      };
+      const result = await cart.checkout({ priceFetcher });
+      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
+      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
+    });
+
+    it("throws RangeError for invalid fetched price", async () => {
+      const cart = new Cart();
+      cart.add(productA, 1);
+      const priceFetcher: PriceFetcher = {
+        fetchPriceCents: vi.fn().mockResolvedValue(-5),
+      };
+      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
+    });
+
+    it("throws RangeError for non-integer fetched price", async () => {
+      const cart = new Cart();
+      cart.add(productA, 1);
+      const priceFetcher: PriceFetcher = {
+        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
+      };
+      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
+    });
+
+    it("propagates priceFetcher rejection", async () => {
+      const cart = new Cart();
+      cart.add(productA, 1);
+      const priceFetcher: PriceFetcher = {
+        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
+      };
+      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("fetch failed");
+    });
+  });
+
+  describe("inventory check", () => {
+    it("passes when all items available", async () => {
+      const cart = new Cart();
+      cart.add(productA, 2);
+      const inventoryChecker: InventoryChecker = {
+        check: vi.fn().mockResolvedValue({ available: true }),
+      };
+      const result = await cart.checkout({ inventoryChecker });
+      expect(result.totals.subtotalCents).toBe(2000);
+      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
+    });
+
+    it("throws InventoryError when item unavailable", async () => {
+      const cart = new Cart();
+      cart.add(productA, 5);
+      const inventoryChecker: InventoryChecker = {
+        check: vi.fn().mockResolvedValue({
+          available: false,
+          availableQuantity: 3,
+          reason: "low stock",
+        }),
+      };
+      try {
+        await cart.checkout({ inventoryChecker });
+        expect.fail("should have thrown");
+      } catch (err) {
+        expect(err).toBeInstanceOf(InventoryError);
+        const invErr = err as InventoryError;
+        expect(invErr.productId).toBe("a");
+        expect(invErr.requested).toBe(5);
+        expect(invErr.available).toBe(3);
+        expect(invErr.message).toBe("low stock");
+      }
+    });
+
+    it("throws InventoryError for partial-stock denial (available but quantity insufficient)", async () => {
+      const cart = new Cart();
+      cart.add(productA, 10);
+      const inventoryChecker: InventoryChecker = {
+        check: vi.fn().mockResolvedValue({
+          available: true,
+          availableQuantity: 5,
+        }),
+      };
+      try {
+        await cart.checkout({ inventoryChecker });
+        expect.fail("should have thrown");
+      } catch (err) {
+        expect(err).toBeInstanceOf(InventoryError);
+        const invErr = err as InventoryError;
+        expect(invErr.productId).toBe("a");
+        expect(invErr.requested).toBe(10);
+        expect(invErr.available).toBe(5);
+      }
+    });
+
+    it("checks items in order and first denial wins", async () => {
+      const cart = new Cart();
+      cart.add(productA, 1);
+      cart.add(productB, 1);
+      const inventoryChecker: InventoryChecker = {
+        check: vi
+          .fn()
+          .mockResolvedValueOnce({ available: true })
+          .mockResolvedValueOnce({ available: false, reason: "out of stock" }),
+      };
+      try {
+        await cart.checkout({ inventoryChecker });
+        expect.fail("should have thrown");
+      } catch (err) {
+        expect(err).toBeInstanceOf(InventoryError);
+        expect((err as InventoryError).productId).toBe("b");
+      }
+    });
+  });
+
+  describe("async tax provider", () => {
+    it("uses asyncTaxProvider for tax calculation", async () => {
+      const cart = new Cart({ region: "US-CA" });
+      cart.add(productA, 1); // subtotal 1000
+      const asyncTaxProvider: AsyncTaxRateProvider = {
+        getRate: vi.fn().mockResolvedValue(0.1),
+      };
+      const result = await cart.checkout({ asyncTaxProvider });
+      expect(result.totals.taxCents).toBe(100);
+      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
+    });
+
+    it("asyncTaxProvider is applied after discount", async () => {
+      const cart = new Cart({
+        discountPolicy: new PercentageDiscountPolicy(50),
+        region: "US",
+      });
+      cart.add(productA, 1); // subtotal 1000, discount 500, discounted 500
+      const asyncTaxProvider: AsyncTaxRateProvider = {
+        getRate: vi.fn().mockResolvedValue(0.1),
+      };
+      const result = await cart.checkout({ asyncTaxProvider });
+      expect(result.totals.taxCents).toBe(50); // 10% of 500
+    });
+
+    it("propagates asyncTaxProvider rejection", async () => {
+      const cart = new Cart();
+      cart.add(productA, 1);
+      const asyncTaxProvider: AsyncTaxRateProvider = {
+        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
+      };
+      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
+        "rate service down",
+      );
+    });
+
+    it("throws RangeError for invalid async rate", async () => {
+      const cart = new Cart();
+      cart.add(productA, 1);
+      const asyncTaxProvider: AsyncTaxRateProvider = {
+        getRate: vi.fn().mockResolvedValue(2.0),
+      };
+      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(RangeError);
+    });
+  });
+
+  describe("full pipeline composition", () => {
+    it("price refresh + inventory + async tax + discount + shipping", async () => {
+      const cart = new Cart({
+        discountPolicy: new PercentageDiscountPolicy(10),
+        shippingCalculator: new FlatShippingCalculator(500),
+        region: "US",
+      });
+      cart.add(productA, 2);
+      cart.add(productB, 1);
+
+      const priceFetcher: PriceFetcher = {
+        fetchPriceCents: vi.fn().mockImplementation((id: string) => {
+          if (id === "a") return Promise.resolve(1200);
+          return Promise.resolve(2500);
+        }),
+      };
+      const inventoryChecker: InventoryChecker = {
+        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
+      };
+      const asyncTaxProvider: AsyncTaxRateProvider = {
+        getRate: vi.fn().mockResolvedValue(0.08),
+      };
+
+      const result = await cart.checkout({
+        priceFetcher,
+        inventoryChecker,
+        asyncTaxProvider,
+      });
+
+      // subtotal: 1200*2 + 2500*1 = 4900
+      expect(result.totals.subtotalCents).toBe(4900);
+      // discount: 10% of 4900 = 490
+      expect(result.totals.discountCents).toBe(490);
+      // discounted: 4410
+      // tax: 8% of 4410 = 352.8 → floor → 352
+      expect(result.totals.taxCents).toBe(352);
+      // shipping: flat 500
+      expect(result.totals.shippingCents).toBe(500);
+      // total: 4410 + 352 + 500 = 5262
+      expect(result.totals.totalCents).toBe(5262);
+    });
+
+    it("checkout without collaborators uses sync path", async () => {
+      const cart = new Cart();
+      cart.add(productA, 1);
+      const result = await cart.checkout();
+      expect(result.totals.subtotalCents).toBe(1000);
+      expect(result.lines).toHaveLength(1);
+    });
+
+    it("returned lines reflect refreshed prices", async () => {
+      const cart = new Cart();
+      cart.add(productA, 1);
+      const priceFetcher: PriceFetcher = {
+        fetchPriceCents: vi.fn().mockResolvedValue(9999),
+      };
+      const result = await cart.checkout({ priceFetcher });
+      expect(result.lines[0]!.product.unitPriceCents).toBe(9999);
+    });
+  });
+});
+
+describe("InventoryError", () => {
+  it("has correct shape and properties", () => {
+    const err = new InventoryError("no stock", "prod-1", 5, 2);
+    expect(err).toBeInstanceOf(Error);
+    expect(err.name).toBe("InventoryError");
+    expect(err.message).toBe("no stock");
+    expect(err.productId).toBe("prod-1");
+    expect(err.requested).toBe(5);
+    expect(err.available).toBe(2);
+  });
+
+  it("available can be undefined", () => {
+    const err = new InventoryError("unknown", "prod-2", 3, undefined);
+    expect(err.available).toBeUndefined();
+  });
+});
+

toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import { refreshPrices } from "../src/inventory.ts";
import type { PriceFetcher } from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("refreshPrices", () => {
  const lines: CartLine[] = [
    { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
    { product: { id: "b", name: "B", unitPriceCents: 200 }, quantity: 1 },
  ];

  it("returns new lines with updated prices", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation((id: string) => {
        if (id === "a") return Promise.resolve(150);
        return Promise.resolve(250);
      }),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(150);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(250);
    expect(result[1]!.quantity).toBe(1);
  });

  it("preserves other product fields", async () => {
    const lineWithWeight: CartLine[] = [
      { product: { id: "a", name: "Heavy", unitPriceCents: 100, weightGrams: 500 }, quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(200),
    };
    const result = await refreshPrices(lineWithWeight, fetcher);
    expect(result[0]!.product.weightGrams).toBe(500);
    expect(result[0]!.product.name).toBe("Heavy");
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-10),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network")),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("network");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

